(()=>{const add=()=>{const side=document.getElementById('side');if(!side||side.querySelector('.github-nav-btn'))return;const labels=[...side.querySelectorAll('.nav-label')];const resources=labels.find(x=>x.textContent.includes('Placement Resources'));const b=document.createElement('button');b.className='nav-btn github-nav-btn';b.innerHTML='⌘ GitHub Profile <span>100%</span>';b.onclick=()=>window.showGithub?.();if(resources)resources.after(resources.nextElementSibling?.classList.contains('github-nav-btn')?null:b);else side.appendChild(b)};new MutationObserver(add).observe(document.body,{childList:true,subtree:true});add()})();